require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['cliente'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT s.*,u.nombre AS cliente,c.id_cotizacion,c.id_administrador,c.diagnostico_preliminar,c.descripcion_trabajo,c.costo_reparacion,c.costo_refacciones,c.costo_total,c.fecha_cotizacion,c.vigencia,c.estado AS estado_cotizacion FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_cliente LEFT JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud WHERE s.id_solicitud=? AND s.id_cliente=?');$q->execute([$id,$_SESSION['usuario']['id_usuario']]);$solicitud=$q->fetch();if(!$solicitud){establecer_mensaje('error','Solicitud no encontrada.');redirigir('mis_solicitudes.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){ $accion=$_POST['accion']??''; if(in_array($accion,['aceptar','rechazar'],true)&&$solicitud['id_cotizacion']&&$solicitud['estado_cotizacion']==='Pendiente'){ $nuevo=$accion==='aceptar'?'Aceptada':'Rechazada';$q=$pdo->prepare('UPDATE cotizaciones SET estado=? WHERE id_cotizacion=?');$q->execute([$nuevo,$solicitud['id_cotizacion']]);$q=$pdo->prepare('UPDATE solicitudes SET estado=? WHERE id_solicitud=?');$q->execute([$nuevo==='Aceptada'?'Aceptada':'Rechazada',$id]);establecer_mensaje('exito','Cotización '.strtolower($nuevo).'.');redirigir('detalle_solicitud.php?id='.$id);} if($accion==='pagar'&&$solicitud['estado']==='Terminada'){ $metodo=$_POST['metodo_pago']??'Efectivo';$ref=trim($_POST['referencia']??'');$q=$pdo->prepare('INSERT INTO pagos (id_solicitud,monto,metodo_pago,fecha_pago,referencia,estado) VALUES (?,?,?,?,?,"Pagado") ON DUPLICATE KEY UPDATE monto=VALUES(monto),metodo_pago=VALUES(metodo_pago),fecha_pago=VALUES(fecha_pago),referencia=VALUES(referencia),estado="Pagado"');$q->execute([$id,$solicitud['costo_total'],$metodo,date('Y-m-d H:i:s'),$ref]);establecer_mensaje('exito','Pago registrado correctamente.');redirigir('detalle_solicitud.php?id='.$id);} }
$q=$pdo->prepare('SELECT r.*,u.nombre AS especialista FROM reparaciones r LEFT JOIN usuarios u ON u.id_usuario=r.id_especialista WHERE r.id_solicitud=?');$q->execute([$id]);$reparacion=$q->fetch();$q=$pdo->prepare('SELECT h.*,u.nombre FROM historial_reparacion h JOIN usuarios u ON u.id_usuario=h.usuario_actualiza WHERE h.id_reparacion=? ORDER BY h.fecha_actualizacion');$q->execute([$reparacion['id_reparacion']??0]);$historial=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM pagos WHERE id_solicitud=? ORDER BY id_pago DESC LIMIT 1');$q->execute([$id]);$pago=$q->fetch();$titulo_pagina='Detalle de solicitud';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">SOLICITUD #<?= $id ?></span><h1><?= escapar($solicitud['marca'].' '.$solicitud['modelo']) ?></h1><p>Registrada el <?= date('d/m/Y H:i',strtotime($solicitud['fecha_solicitud'])) ?></p></div><span class="<?= estado_clase($solicitud['estado']) ?>"><?= escapar($solicitud['estado']) ?></span></div><div class="rejilla-dos"><section class="tarjeta"><h3>Información reportada</h3><div class="fila-detalle"><span>Tipo</span><strong><?= escapar($solicitud['tipo_consola']) ?></strong></div><div class="fila-detalle"><span>Problema</span><strong><?= escapar($solicitud['problema_reportado']) ?></strong></div><div class="fila-detalle"><span>Serie</span><strong><?= escapar($solicitud['numero_serie']?:'No indicada') ?></strong></div><p><?= nl2br(escapar($solicitud['descripcion'])) ?></p></section><section class="tarjeta"><h3>Cotización</h3><?php if(!$solicitud['id_cotizacion']): ?><div class="vacio">El administrador aún está revisando tu solicitud.</div><?php else: ?><p><?= nl2br(escapar($solicitud['descripcion_trabajo'])) ?></p><div class="fila-detalle"><span>Diagnóstico</span><strong><?= escapar($solicitud['diagnostico_preliminar']) ?></strong></div><div class="fila-detalle"><span>Reparación</span><strong>$<?= number_format($solicitud['costo_reparacion'],2) ?></strong></div><div class="fila-detalle"><span>Refacciones</span><strong>$<?= number_format($solicitud['costo_refacciones'],2) ?></strong></div><div class="fila-detalle"><span>Total</span><strong class="texto-verde">$<?= number_format($solicitud['costo_total'],2) ?></strong></div><?php if($solicitud['estado_cotizacion']==='Pendiente'): ?><form method="post" class="acciones"><button class="boton" name="accion" value="aceptar">Aceptar cotización</button><button class="boton boton-rojo" name="accion" value="rechazar" data-confirmar="¿Seguro que deseas rechazar esta cotización?">Rechazar</button></form><?php else: ?><p><span class="<?= estado_clase($solicitud['estado_cotizacion']) ?>"><?= escapar($solicitud['estado_cotizacion']) ?></span></p><?php endif; ?><?php endif; ?></section></div><?php if($reparacion): ?><section class="tarjeta" style="margin-top:18px"><h3>Proceso de reparación · <?= escapar($reparacion['especialista']) ?></h3><div class="barra-progreso"><?php $estados=['Solicitud','Diagnóstico','En reparación','En pruebas','Terminada'];$indice=array_search($reparacion['estado'],['Pendiente','Diagnóstico','En reparación','En pruebas','Terminada']);foreach($estados as $i=>$e): ?><div class="paso-progreso <?= $i <= $indice?'activo':'' ?>"><i><?= $i+1 ?></i><span><?= $e ?></span></div><?php endforeach; ?></div><?php if($historial): ?><div class="tabla-contenedor"><table class="tabla"><thead><tr><th>Fecha</th><th>Cambio</th><th>Comentario</th></tr></thead><tbody><?php foreach($historial as $h): ?><tr><td><?= date('d/m/Y H:i',strtotime($h['fecha_actualizacion'])) ?></td><td><?= escapar($h['estado_anterior']?:'Inicio') ?> → <strong><?= escapar($h['estado_nuevo']) ?></strong></td><td><?= escapar($h['comentario']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?><?php if($solicitud['estado']==='Terminada' && (!$pago || $pago['estado']!=='Pagado')): ?><section class="tarjeta" style="margin-top:18px"><h3>Registrar pago</h3><p>Total a pagar: <strong class="texto-verde">$<?= number_format($solicitud['costo_total'],2) ?> MXN</strong></p><form method="post" class="formulario"><input type="hidden" name="accion" value="pagar"><div class="rejilla-dos"><label>Método<select name="metodo_pago"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option></select></label><label>Referencia <small>(opcional)</small><input name="referencia"></label></div><button class="boton" type="submit">Confirmar pago</button></form></section><?php elseif($pago): ?><p class="alerta alerta-exito">Pago <?= escapar($pago['estado']) ?> · <?= escapar($pago['metodo_pago']) ?></p><?php endif; ?><?php require_once __DIR__.'/../includes/pie.php'; ?>


